CREATE TABLE IF NOT EXISTS books (id SERIAL PRIMARY KEY, title VARCHAR(150) NOT NULL, author VARCHAR(100) NOT NULL, year INTEGER NOT NULL, is_available BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS readers (id SERIAL PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS loans (id SERIAL PRIMARY KEY, book_id INTEGER NOT NULL REFERENCES books(id), reader_id INTEGER NOT NULL REFERENCES readers(id), loan_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, return_date TIMESTAMP NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_loan ON loans(book_id) WHERE return_date IS NULL;
